import { useState } from "react";

function Form() {
    const [list, useList] = useState(['', 'Komedia o wartości 1', 'Obyczajowy o wartości 2', 'Sensacyjny o wartości 3', 'Horror o wartości 4']);
  return (

    <form>
        <label>Tytuł filmu</label>
        <input type="text" /> <br/>

        <label>Rodzaj</label>
        <select>
            {list.map((value, index) => (
                <option>{value}</option>
            ))}
        </select>
    </form>
  );
}

export default Form;
